pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, bytes16(0), address(this), address(this), address(this));
    }

    function testFuzz_property(address ward, address caller) public {
        // ward must be different from caller to create a sender/tx.origin mismatch
        vm.assume(ward != caller);
        // caller must not be the zero address
        vm.assume(caller != address(0));

        // Make `ward` an authorized user
        vm.prank(address(this));
        c.rely(ward);

        // Deploy a proxy that will forward the updatePrice call
        Proxy proxy = new Proxy(c);

        // ward calls updatePrice through the proxy
        vm.prank(ward);
        bool ok;
        try proxy.forward() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract must revert because msg.sender (proxy) is not a ward
        // The mutant allows it because it checks tx.origin (ward) which is authorized
        assertTrue(!ok);
    }
}

contract Proxy {
    C immutable c;
    constructor(C _c) {
        c = _c;
    }
    function forward() external {
        c.updatePrice(1);
    }
}

