pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(uint256 realTotalSupply) public {
        // Ensure total supply is within a reasonable range to avoid overflow in mock
        vm.assume(realTotalSupply > 0 && realTotalSupply <= type(uint128).max);

        // Deploy a mock InvestmentManager that returns realTotalSupply + 1 for totalAssets
        MockInvestmentManager mock = new MockInvestmentManager();
        // Make the mock return realTotalSupply + 1 when totalAssets is called with (realTotalSupply, address(c))
        mock.setExpectedReturn(realTotalSupply + 1);

        // Set the mock as the investment manager in C
        c.file("investmentManager", address(mock));

        // Set the total supply of the share token to realTotalSupply
        // We need the share token to return realTotalSupply. Since address(this) is the share, we deploy a mock share.
        MockShare mockShare = new MockShare();
        mockShare.setTotalSupply(realTotalSupply);

        // Redeploy C with the mock share
        c = new C(0, bytes16(0), address(this), address(mockShare), address(mock));

        // In the reference version, totalAssets() should call investmentManager.totalAssets(totalSupply(), address(this))
        // In the buggy version, totalAssets() just returns totalSupply()
        // Since totalSupply() is realTotalSupply, and mock returns realTotalSupply + 1, the values will differ.
        uint256 result = c.totalAssets();
        assertTrue(result == realTotalSupply + 1);
    }
}

