pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(uint256 dummyTotalSupply, uint256 dummyLiquidity) public {
        // The investmentManager (address(this)) is called by totalAssets(); we need
        // to simulate a return that depends on its first argument so that the bug
        // (passing 0) is observable.  We use a tiny helper that returns the first
        // argument as the totalAssets to make the difference computable without
        // mocking.  The helper is deployed and we replace the address used in setUp
        // via a public file("investmentManager", helper) that anyone can call.
        // That replacement is needed because in setUp() the investmentManager is set to
        // address(this). We deploy a minimal helper that returns callData[4:36] as
        // totalAssets.
        vm.assume(dummyTotalSupply > 0);
        AdversarialIM im = new AdversarialIM();
        vm.prank(address(this)); // we are a ward (set in constructor)
        c.file("investmentManager", address(im));

        // Simulate the share returning a totalSupply so that the reference uses it
        // while the bug ignores it.  Share is also address(this) initially, so we deploy
        // a tiny helper that returns dummyTotalSupply for totalSupply().
        ShareMimic share = new ShareMimic(dummyTotalSupply);
        vm.prank(address(this));
        c.file("investmentManager", address(im)); // already done, but harmless
        // Unfortunately we cannot change "share" via file; the share is immutable.
        // But the reference calls share.totalSupply() inside totalAssets(), and we control
        // whatever that returns. Since share is address(this) initially, we must make
        // address(this) behave like a TrancheTokenLike returning dummyTotalSupply.
        // We will deploy ShareMimic and use it as the share address in a new C.
        // We redeploy C with the share helper to allow the fuzzer to vary totalSupply.
        // This is done once per test, which is acceptable because the invariant must hold
        // for any C deployment.
        C c2 = new C(0, bytes16(0), address(this), address(share), address(im));

        // Compute what the correct totalAssets should be given the AdversarialIM
        // which returns its first argument as the result.
        uint256 ref = c2.totalAssets(); // correct: calls investmentManager.totalAssets(dummyTotalSupply, address(c2))

        // Now simulate the buggy version manually: we call the IM directly with 0 and the pool address,
        // which is what the mutant does.
        uint256 bug = im.totalAssets(0, address(c2));

        assertTrue(ref != bug);
    }
}

contract AdversarialIM {
    // Minimal mock that returns the first argument as totalAssets.
    function totalAssets(uint256 totalSupply, address /* pool */) external pure returns (uint256) {
        return totalSupply;
    }
    function totalSupply() external view returns (uint256) {}
}

contract ShareMimic {
    uint256 public totalSupplyVal;
    constructor(uint256 _totalSupply) { totalSupplyVal = _totalSupply; }
    function totalSupply() external view returns (uint256) { return totalSupplyVal; }
    function name() external view returns (string memory) { return ""; }
    function symbol() external view returns (string memory) { return ""; }
    function decimals() external view returns (uint8) { return 18; }
    function balanceOf(address) external view returns (uint256) { return 0; }
    function allowance(address, address) external view returns (uint256) { return 0; }
    function checkTransferRestriction(address, address, uint256) external view returns (bool) { return false; }
    function permit(address, address, uint256, uint256, uint8, bytes32, bytes32) external {}
    function PERMIT_TYPEHASH() external view returns (bytes32) {}
    function DOMAIN_SEPARATOR() external view returns (bytes32) {}
}

